CURRENCY = "CNY"
def authorize(record, actor):
    if actor != "admin" and actor != record["owner"]:
        raise PermissionError("not your record")
def render(record):
    return f"{record['id']}:{CURRENCY} {record['amount']:.2f}"

files.app/exporter.py:
from app import policy
def export_one(record, actor):
    policy.authorize(record, actor)
    return policy.render(record)

files.tests/test_exporter.py:
import unittest
from app.exporter import export_one
class ExportTest(unittest.TestCase):
    def test_owner(self):
        self.assertEqual(export_one({"id":1,"owner":"lin","amount":12},"lin"),"1:CNY 12.00")
    def test_denied(self):
        with self.assertRaises(PermissionError):
            export_one({"id":1,"owner":"lin","amount":12},"other")

